SELECT id,forecast_id,base_forecast_id,name,created_at,jsonb_build_object('SchemaVersion',payload->'SchemaVersion','Changes',payload->'Changes','SalesChanges',payload->'SalesChanges') FROM core_scenarios WHERE company_id=$1 AND account_id=$2 AND ($3='00000000-0000-0000-0000-000000000000'::uuid OR base_forecast_id=$3) AND ($4='00000000-0000-0000-0000-000000000000'::uuid OR id<$4) ORDER BY id DESC LIMIT $5;
